{"new_str": "#' Log-space difference of exponentials: log(exp(a) - exp(b)) for a > b.
#' Returns -Inf when the difference is negligible. Vectorized over a and b.
log_diff_exp <- function(a, b) {
  if (length(a) != length(b)) stop("a and b must have the same length")
  result <- numeric(length(a))
  for (i in seq_along(a)) {
    ai <- a[i]; bi <- b[i]
    if (!is.finite(ai) || !is.finite(bi)) {
      result[i] <- -Inf
    } else if (ai <= bi) {
