{"content": "# Quick debug script for ARS - standalone, no auto-test
logsumexp <- function(x) {
  if (length(x) == 0) return(-Inf)
  max_x <- max(x, na.rm = TRUE)
  if (!is.finite(max_x)) return(-Inf)
  max_x + log(sum(exp(x - max_x)))
}

log_diff_exp <- function(a, b) {
  if (length(a) != length(b)) stop("a and b must have the same length")
  result <- numeric(length(a))
  for (i in seq_along(a)) {
    ai <- a[i]; bi <- b[i]
    if (!is.finite(ai) || !is.finite(bi)) {
      result[i] <- -Inf
    } else if (ai <= bi) {
      result[i] <- -Inf
    } else if ((ai - bi) < -700) {
      result[i] <- -Inf
    } else {
      result[i] <- bi + log(exp(ai - bi) - 1)
    }
  }
  result
}

segment_log_area <- function(a, b, h) {
  if (abs(b) < 1e-12) {
    return(log(h) + a)
  }
  if (b > 0) {
    return(log_diff_exp(a + b * h, a) - log(b))
  } else {
    return(log_diff_exp(a, a + b * h) - log(-b))
  }
}

segment_log_areas <- function(a, b, h) {
  result <- numeric(length(a))
  flat_mask <- abs(b) < 1e-12
  result[flat_mask] <- log(h[flat_mask]) + a[flat_mask]
  pos_mask <- !flat_mask & b > 0
  if (any(pos_mask)) {
    result[pos_mask] <- log_diff_exp(a[pos_mask] + b[pos_mask] * h[pos_mask], a[pos_mask]) - log(b[pos_mask])
  }
  neg_mask <- !flat_mask & b <= 0
  if (any(neg_mask)) {
    result[neg_mask] <- log_diff_exp(a[neg_mask], a[neg_mask] + b[neg_mask] * h[neg_mask]) - log(-b[neg_mask])
  }
  result
}

compute_envelope <- function(x, logy) {
  n <- length(x)
  h <- diff(x)
  slopes <- diff(logy) / h
  a <- logy[-n] - slopes * x[-n]
  b <- slopes
  log_areas <- segment_log_areas(a, b, h)
  logZ <- logsumexp(log_areas)
  list(a = a, b = b, logZ = logZ)
}

sample_from_envelope <- function(envelope, x, n_sample) {
  n <- length(x)
  h <- diff(x)
  a <- envelope$a
  b <- envelope$b
  logZ <- envelope$logZ
  log_areas <- segment_log_areas(a, b, h)
  probs <- exp(log_areas - logZ)
  probs[is.na(probs) | probs <= 0] <- .Machine$double.eps
  probs <- probs / sum(probs)
  seg_idx <- sample(seq_len(n - 1), size = n_sample, replace = TRUE, prob = probs)
  samples <- numeric(n_sample)
  u <- runif(n_sample)
  for (k in seq_len(n_sample)) {
    i <- seg_idx[k]
    ui <- u[k]
    bi <- b[i]
    if (abs(bi) < 1e-12) {
      samples[k] <- x[i] + ui * h[i]
    } else {
      samples[k] <- x[i] + log(1 + ui * (exp(bi * h[i]) - 1)) / bi
    }
  }
  samples
}

ars <- function(logdensity, x0, lower = -Inf, upper = Inf, n, max_support = 100) {
  x <- sort(x0)
  logy <- logdensity(x)
  n_support <- length(x)
  envelope <- compute_envelope(x, logy)
  samples <- numeric(n)
  n_generated <- 0
  n_rejected <- 0
  max_iter <- max(n * 200, 20000)

  while (n_generated < n && n_rejected < max_iter) {
    cand <- sample_from_envelope(envelope, x, 1)
    log_target <- logdensity(cand)
    if (!is.finite(log_target)) {
      n_rejected <- n_rejected + 1
      next
    }
    seg <- findInterval(cand, x, rightmost.closed = FALSE)
    if (seg >= n_support) seg <- n_support - 1
    if (seg < 1) seg <- 1
    log_env <- envelope$a[seg] + envelope$b[seg] * (cand - x[seg])
    u <- runif(1)
    if (log(u) <= log_target - log_env) {
      n_generated <- n_generated + 1
      samples[n_generated] <- cand
    } else {
      n_rejected <- n_rejected + 1
      if (n_support < max_support) {
        x <- c(x, cand)
        logy <- c(logy, logdensity(cand))
        idx <- order(x)
        x <- x[idx]
        logy <- logy[idx]
        n_support <- length(x)
        envelope <- compute_envelope(x, logy)
      }
    }
  }
  samples
}

