{"command": "cd /app && timeout 30 Rscript -e '
# Debug the ARS sampler step by step
x <- c(-3, 0, 3)
logy <- c(-4.5, 0, -4.5)
h <- diff(x)
slopes <- diff(logy) / h
a <- logy[-length(x)] - slopes * x[-length(x)]
b <- slopes

cat("a:", a, "\n")
cat("b:", b, "\n")

# log_diff_exp
log_diff_exp <- function(a, b) {
  result <- numeric(length(a))
  for (i in seq_along(a)) {
    ai <- a[i]; bi <- b[i]
    if (!is.finite(ai) || !is.finite(bi) || ai <= bi || (ai - bi) < -700) {
      result[i] <- -Inf
    } else {
      result[i] <- bi + log(exp(ai - bi) - 1)
    }
  }
  result
}

log_areas <- segment_log_areas <- function(a, b, h) {
  result <- numeric(length(a))
  flat_mask <- abs(b) < 1e-12
  result[flat_mask] <- log(h[flat_mask]) + a[flat_mask]
  pos_mask <- !flat_mask & b > 0
  if (any(pos_mask)) {
    result[pos_mask] <- log_diff_exp(a[pos_mask] + b[pos_mask] * h[pos_mask], a[pos_mask]) - log(b[pos_mask])
  }
  neg_mask <- !flat_mask & b <= 0
  if (any(neg_mask)) {
    result[neg_mask] <- log_diff_exp(a[neg_mask], a[neg_mask] + b[neg_mask] * h[neg_mask]) - log(-b[neg_mask])
  }
  result
}

log_areas <- segment_log_areas(a, b, h)
cat("log_areas:", log_areas, "\n")
logZ <- max(log_areas) + log(sum(exp(log_areas - max(log_areas))))
cat("logZ:", logZ, "\n")

# Now sample from envelope
n_sample <- 5
seg_idx <- sample(1:2, n_sample, replace=TRUE, prob=exp(log_areas - logZ))
cat("seg_idx:", seg_idx, "\n")
' 2>&1"}

